class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])

        # Clockwise order in screen coordinates (rows increase downward).
        # A turn from directions[i] goes to directions[(i + 1) % 4].
        directions = [(-1, -1), (-1, 1), (1, 1), (1, -1)]

        ans = 0

        # q is the direction after the clockwise turn.
        # The first-leg direction is its preceding clockwise direction.
        for q_idx, (qr, qc) in enumerate(directions):
            dr, dc = directions[(q_idx - 1) % 4]

            # run0/run2: alternating suffix lengths in q direction,
            # conditional on the current position needing 0 or 2.
            run0 = [[0] * m for _ in range(n)]
            run2 = [[0] * m for _ in range(n)]

            # Process opposite q so (r + qr, c + qc) is already known.
            row_order = range(n - 1, -1, -1) if qr == 1 else range(n)
            col_order = range(m - 1, -1, -1) if qc == 1 else range(m)

            for r in row_order:
                for c in col_order:
                    nr, nc = r + qr, c + qc

                    if grid[r][c] == 0:
                        run0[r][c] = 1
                        if 0 <= nr < n and 0 <= nc < m:
                            run0[r][c] += run2[nr][nc]
                    elif grid[r][c] == 2:
                        run2[r][c] = 1
                        if 0 <= nr < n and 0 <= nc < m:
                            run2[r][c] += run0[nr][nc]

            # first[r][c]: longest valid 1,2,0,2,... first leg that
            # ends at (r, c), moving in (dr, dc).
            first = [[0] * m for _ in range(n)]

            # The predecessor lies in a previous/next row according to dr.
            row_order = range(n) if dr == 1 else range(n - 1, -1, -1)

            for r in row_order:
                for c in range(m):
                    value = grid[r][c]

                    if value == 1:
                        first[r][c] = 1
                    else:
                        pr, pc = r - dr, c - dc
                        if 0 <= pr < n and 0 <= pc < m:
                            prev_len = first[pr][pc]
                            if prev_len:
                                expected = 2 if (prev_len & 1) else 0
                                if value == expected:
                                    first[r][c] = prev_len + 1

                    length = first[r][c]
                    if length == 0:
                        continue

                    ans = max(ans, length)

                    # Continue after a clockwise turn. The pivot itself is
                    # already included in length, so begin at its q-neighbor.
                    nr, nc = r + qr, c + qc
                    if 0 <= nr < n and 0 <= nc < m:
                        expected = 2 if (length & 1) else 0
                        suffix = run2[nr][nc] if expected == 2 else run0[nr][nc]
                        ans = max(ans, length + suffix)

        return ans

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        parts = p.split('*')  # Exactly three parts: A, B, C
        literals = [part for part in parts if part]

        # Pattern "**" matches the empty substring.
        if not literals:
            return 0

        n = len(s)

        def find_occurrences(pattern):
            m = len(pattern)
            pi = [0] * m

            for i in range(1, m):
                j = pi[i - 1]
                while j > 0 and pattern[i] != pattern[j]:
                    j = pi[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                pi[i] = j

            positions = []
            j = 0
            for i, ch in enumerate(s):
                while j > 0 and ch != pattern[j]:
                    j = pi[j - 1]
                if ch == pattern[j]:
                    j += 1
                if j == m:
                    positions.append(i - m + 1)
                    j = pi[j - 1]

            return positions

        occurrences = [find_occurrences(part) for part in literals]

        if not occurrences[0]:
            return -1

        # A single literal with stars around it can match that literal itself.
        if len(literals) == 1:
            return len(literals[0])

        def build_successor_array(positions):
            present = bytearray(n + 1)
            for pos in positions:
                present[pos] = 1

            nxt = [-1] * (n + 1)
            nearest = -1
            for i in range(n, -1, -1):
                if present[i]:
                    nearest = i
                nxt[i] = nearest
            return nxt

        successor_arrays = [None]
        for i in range(1, len(literals)):
            successor_arrays.append(build_successor_array(occurrences[i]))

        answer = float("inf")

        for start in occurrences[0]:
            current_end = start + len(literals[0])
            valid = True

            for i in range(1, len(literals)):
                next_start = successor_arrays[i][current_end]
                if next_start == -1:
                    valid = False
                    break
                current_end = next_start + len(literals[i])

            if valid:
                answer = min(answer, current_end - start)

        return -1 if answer == float("inf") else answer

